/** Every text style without its own font gets the body font (web only; native keeps the system font). */
function withFonts<T extends Record<string,object>>(styles:T):T{if(!SANS)return styles;return Object.fromEntries(Object.entries(styles).map(([k,v])=>[k,'fontSize' in v&&!('fontFamily' in v&&(v as {fontFamily?:string}).fontFamily)?{...v,fontFamily:SANS}:v])) as T}
function useStyles(){const {rtl}=useI18n();const theme=activeTheme;return useMemo(()=>{const styles=withFonts(themeStyles(baseStyles,theme));if(rtl)return styles;return Object.fromEntries(Object.entries(styles).map(([key,style])=>{const value:Record<string,unknown>={...style};if(value.textAlign==='right')value.textAlign='left';if(value.flexDirection==='row-reverse')value.flexDirection='row';else if(value.flexDirection==='row')value.flexDirection='row-reverse';for(const k of ['alignItems','alignSelf'])if(value[k]==='flex-end')value[k]='flex-start';if(value.borderRightWidth!==undefined){value.borderLeftWidth=value.borderRightWidth;delete value.borderRightWidth}else if(value.borderLeftWidth!==undefined){value.borderRightWidth=value.borderLeftWidth;delete value.borderLeftWidth}return [key,value]})) as typeof baseStyles},[rtl,theme])}

